"use client";

/**
 * 改造自 shadcn 原装 base-lyra collapsible（https://ui.shadcn.com/r/styles/base-lyra/collapsible.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021）。`Collapsible` 收 `motion`，经 context 交给 `CollapsibleContent`。
 *    缺省 `expand`：面板渲染 `data-motion="expand"`，高度取 Base UI 给的 `--collapsible-panel-height`，
 *    展开时从 0 长到内容高度并淡入，收起时沿原路退回。`none` 与上游一致：面板直接出现、直接消失。
 * 此外只有格式化（分号）。
 */
import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible";
import { createContext, use } from "react";

/**
 * 折叠面板支持的动效预设（ADR 0021）。缺省 `expand`。
 * - `expand`：高度从 0 长到内容高度并淡入，250ms；收起 200ms。
 * - `none`：面板直接出现、直接消失。
 */
type CollapsibleMotion = "none" | "expand";

const CollapsibleMotionContext = createContext<CollapsibleMotion>("expand");

function Collapsible({
  motion = "expand",
  ...props
}: CollapsiblePrimitive.Root.Props & { motion?: CollapsibleMotion }) {
  return (
    <CollapsibleMotionContext value={motion}>
      <CollapsiblePrimitive.Root data-slot="collapsible" {...props} />
    </CollapsibleMotionContext>
  );
}

function CollapsibleTrigger({ ...props }: CollapsiblePrimitive.Trigger.Props) {
  return <CollapsiblePrimitive.Trigger data-slot="collapsible-trigger" {...props} />;
}

function CollapsibleContent({ ...props }: CollapsiblePrimitive.Panel.Props) {
  const motion = use(CollapsibleMotionContext);
  return (
    <CollapsiblePrimitive.Panel
      data-slot="collapsible-content"
      data-motion={motion === "none" ? undefined : motion}
      {...props}
    />
  );
}

export { Collapsible, CollapsibleContent, type CollapsibleMotion, CollapsibleTrigger };
